def parse_duration(s: str) -> int:
    """
    Parse a compact duration string into total seconds.
    """
    if not s:
        raise ValueError("Input string is empty")

    components = []
    i = 0

    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            components.append(int(s[i:j]))
            i = j
        elif s[i] == 'h':
            if not components:
                raise ValueError("No hours specified before 'h'")
            components[-1] *= 3600
            i += 1
        elif s[i] == 'm':
            if not components:
                raise ValueError("No minutes specified before 'm'")
            components[-1] *= 60
            i += 1
        elif s[i] == 's':
            if not components:
                raise ValueError("No seconds specified before 's'")
            components[-1] = int(components[-1])
            i += 1
        else:
            raise ValueError(f"Invalid character in input string: {s[i]}")

    if not components:
        raise ValueError("No valid duration components found")

    return sum(components)
